local Camera = game:GetService("Workspace").CurrentCamera;

local BallisticsHandler = require(game:GetService("ReplicatedStorage").Dependencies.BallisticsHandler);
local PlayerModule = require(game:GetService("ReplicatedFirst").PlayerModule);

local CharacterHandler = PlayerModule.CharacterHandler;

local function ClosestTarget(Range: number)
    local ClosestPart, ClosestDistance = nil, Range;

    for _, Player in (CharacterHandler.Capsules) do
        local Character = CharacterHandler:GetCharacterFromCapsule(Player);
        if (not Character) then
            continue;
        end
        if (Character.Player.Team.Name == PlayerModule.Character.CurrentCharacter.Team) then
            continue;
        end
        local Head = Character.Model.Human.Head;
        local ScreenPosition, OnScreen = Camera:WorldToViewportPoint(Head.Position);
        if (not OnScreen) then
            continue;
        end
        local Distance = (Vector2.new(ScreenPosition.X, ScreenPosition.Y) - Camera.ViewportSize / 2).Magnitude;
        if (Distance < ClosestDistance) then
            ClosestDistance = Distance;
            ClosestPart = Head;
        end
    end

    return ClosestPart;
end

local Old; Old = hookfunction(BallisticsHandler.Fire, function(self, Origin, Direction, Stats, Replicated, IgnoreList, Seed1, Seed2, ServerTime)
    local Closest = ClosestTarget(1000);
    if (Closest) then
        Direction = (Closest.Position - Origin).Unit;
    end
    return Old(self, Origin, Direction, Stats, Replicated, IgnoreList, Seed1, Seed2, ServerTime);
end)

local camera = game:GetService("Workspace").CurrentCamera;

local ballistic_handler = require(game:GetService("ReplicatedStorage"):FindFirstChild("Dependencies"):FindFirstChild("BallisticsHandler"), true);
local player = require(game:GetService("ReplicatedFirst"):FindFirstChild("PlayerModule"), true);

local character_handler = player.CharacterHandler;

function closest_target(range: number)
    local closest_part, closest_distance = nil, range;

    for _, player in (character_handler.Capsules) do
        local character = character_handler:GetCharacterFromCapsule(player);
        if (not character) then
            continue;
        end
        local head = character.Model.Human.Head;
        local screen_position, on_screen = camera:WorldToViewportPoint(head.Position);
        if (not on_screen) then
            continue;
        end
        local distance = (Vector2.new(screen_position.X, screen_position.Y) - camera.ViewportSize / 2).Magnitude;
        if (distance < closest_distance) then
            closest_part = head;
            closest_distance = distance;
        end
    end

    return closest_part;
end

local old; old = hookfunction(ballistic_handler.Fire, function(self, origin, direction, stats, replicated, ignore_list, seed1, seed2, server_time)
    local closest = closest_target(999);
    if (closest) then
        stats.Stats.Velocity = 99999;
        direction = (closest.Position - origin).Unit;
    end
    return old(self, origin, direction, stats, replicated, ignore_list, seed1, seed2, server_time);
end);
